{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C61"],
      "claim": "Sumatriptan, the closest analogue, has low absolute oral bioavailability of 14% in humans due to first-pass metabolism; however, the query replaces its N-methylsulfonamide with a pyrrolidine sulfonamide, a modification that increases lipophilicity and removes a sulfonamide N-H, so this low value does not directly transfer.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C38"],
      "claim": "Zolmitriptan, which shares the same dimethylaminoethyl side chain and indole core but has a different 5-substituent, has an absolute oral bioavailability of about 49%, demonstrating that this scaffold can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Rizatriptan, another close analogue with the same side chain and a 5-triazolylmethyl substituent, has an absolute oral bioavailability of approximately 40%, supporting high bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C62"],
      "claim": "Eletriptan, a triptan containing a pyrrolidine motif and a sulfone-containing 5-substituent, has an absolute oral bioavailability of approximately 50%, supporting the high-F potential of the query's pyrrolidine sulfonamide.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C64"],
      "claim": "Naratriptan, a sulfonamide-containing triptan, has oral bioavailability of 63-74% in humans, showing that sulfonamide triptans can be highly bioavailable.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is almotriptan, a triptan with a pyrrolidine sulfonamide at the 5-position. Although the closest analogue sumatriptan has low bioavailability (14%), the pyrrolidine sulfonamide modification is known to improve bioavailability, and multiple close triptan analogues with 5-substituents (zolmitriptan, rizatriptan, eletriptan, naratriptan) have F >= 40%. Therefore the query is predicted to have high oral bioavailability (F >= 20%).",
  "evidence_gaps": [
    "No direct experimental bioavailability record for the query (almotriptan) is present in the supplied evidence set.",
    "The quantitative effect of replacing the N-methylsulfonamide with pyrrolidine sulfonamide on first-pass metabolism is inferred from analogue data rather than measured for the query.",
    "Human absolute F for the query may vary with formulation and dose, though the threshold is 20% and most analogues are well above it."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

